57	// DetectPresence checks if Claude Code is configured in the repository.
58	func (c *ClaudeCodeAgent) DetectPresence(ctx context.Context) (bool, error) {
59		// Get worktree root to check for .claude directory
60		// This is needed because the CLI may be run from a subdirectory
61		repoRoot, err := paths.WorktreeRoot(ctx)
62		if err != nil {
63			// Not in a git repo, fall back to CWD-relative check
64			repoRoot = "."
65		}
66	
67		// Check for .claude directory
68		claudeDir := filepath.Join(repoRoot, ".claude")
69		if _, err := os.Stat(claudeDir); err == nil {
70			return true, nil
71		}
72		// Check for .claude/settings.json
73		settingsFile := filepath.Join(repoRoot, ".claude", "settings.json")
74		if _, err := os.Stat(settingsFile); err == nil {
75			return true, nil
76		}
77		return false, nil
78	}
