121	// ReadSession reads a session from Claude's storage (JSONL transcript file).
122	// The session data is stored in NativeData as raw JSONL bytes.
123	// ModifiedFiles is computed by parsing the transcript.
124	func (c *ClaudeCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
125		if input.SessionRef == "" {
126			return nil, errors.New("session reference (transcript path) is required")
127		}
128	
129		// Read the raw JSONL file
130		data, err := os.ReadFile(input.SessionRef)
131		if err != nil {
132			return nil, fmt.Errorf("failed to read transcript: %w", err)
133		}
134	
135		// Parse to extract computed fields
136		lines, err := transcript.ParseFromBytes(data)
137		if err != nil {
138			return nil, fmt.Errorf("failed to parse transcript: %w", err)
139		}
140	
141		return &agent.AgentSession{
142			SessionID:     input.SessionID,
143			AgentName:     c.Name(),
144			SessionRef:    input.SessionRef,
145			StartTime:     time.Now(),
146			NativeData:    data,
147			ModifiedFiles: ExtractModifiedFiles(lines),
148		}, nil
149	}
