151	// WriteSession writes a session to Claude's storage (JSONL transcript file).
152	// Uses the NativeData field which contains raw JSONL bytes.
153	// The session must have been created by Claude Code (AgentName check).
154	func (c *ClaudeCodeAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
155		if session == nil {
156			return errors.New("session is nil")
157		}
158	
159		// Verify this session belongs to Claude Code
160		if session.AgentName != "" && session.AgentName != c.Name() {
161			return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
162		}
163	
164		if session.SessionRef == "" {
165			return errors.New("session reference (transcript path) is required")
166		}
167	
168		if len(session.NativeData) == 0 {
169			return errors.New("session has no native data to write")
170		}
171	
172		// Write the raw JSONL data
173		if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
174			return fmt.Errorf("failed to write transcript: %w", err)
175		}
176	
177		return nil
178	}
