347	// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
348	// detects file changes, saves step + checkpoint, transitions phase.
349	//
350	//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
351	func handleLifecycleTurnEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
352		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
353		logging.Info(logCtx, "turn-end",
354			slog.String("event", event.Type.String()),
355			slog.String("session_id", event.SessionID),
356			slog.String("session_ref", event.SessionRef),
357			slog.String("model", event.Model),
358		)
359	
360		sessionID := event.SessionID
361		if sessionID == "" {
362			sessionID = unknownSessionID
363		}
364	
365		// Fill model from hint file if the agent didn't provide it on this hook
366		if event.Model == "" && sessionID != unknownSessionID {
367			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
368				event.Model = hint
369				logging.Debug(logCtx, "loaded model from hint file",
370					slog.String("model", hint))
371			}
372		}
373	
374		transcriptRef := event.SessionRef
375		if transcriptRef == "" {
376			return errors.New("transcript file not specified")
377		}
378	
379		// If agent implements TranscriptPreparer, materialize the transcript file.
380		// This must run BEFORE fileExists: agents like OpenCode lazily fetch transcripts
381		// via `opencode export`, so the file doesn't exist until PrepareTranscript creates it.
382		// Claude Code's PrepareTranscript just flushes (always succeeds). Agents without
383		// TranscriptPreparer (Gemini, Droid) are unaffected.
384		_, prepareSpan := perf.Start(ctx, "prepare_and_validate_transcript")
385		if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
386			if err := preparer.PrepareTranscript(ctx, transcriptRef); err != nil {
387				logging.Warn(logCtx, "failed to prepare transcript",
388					slog.String("error", err.Error()))
389			}
390		}
391	
392		if !fileExists(transcriptRef) {
393			prepareSpan.RecordError(fmt.Errorf("transcript file not found: %s", transcriptRef))
394			prepareSpan.End()
395			return fmt.Errorf("transcript file not found: %s", transcriptRef)
396		}
397	
398		// Early check: bail out quickly if the repo has no commits yet.
399		// Return nil (not an error) so the hook exits 0 — agents treat non-zero
400		// exit codes as hook failures. The user was already warned at session start.
401		if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
402			prepareSpan.End()
403			logging.Info(logCtx, "skipping checkpoint - will activate after first commit")
404			return nil
405		}
406		prepareSpan.End()
407	
408		// Create session metadata directory
409		_, copySpan := perf.Start(ctx, "copy_transcript")
410		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
411		sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
412		if err != nil {
413			sessionDirAbs = sessionDir
414		}
415		if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
416			copySpan.RecordError(err)
417			copySpan.End()
418			return fmt.Errorf("failed to create session directory: %w", err)
419		}
420	
421		// Copy transcript to session directory
422		transcriptData, err := ag.ReadTranscript(transcriptRef)
423		if err != nil {
424			copySpan.RecordError(err)
425			copySpan.End()
426			return fmt.Errorf("failed to read transcript: %w", err)
427		}
428		logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
429		if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {

