189	// --- Transcript flush sentinel ---
190	
191	// stopHookSentinel is the string that appears in Claude Code's hook_progress
192	// entry when the stop hook has been invoked, indicating the transcript is fully flushed.
193	const stopHookSentinel = "hooks claude-code stop"
194	
195	// waitForTranscriptFlush polls the transcript file for the stop hook sentinel.
196	// Falls back silently after a timeout.
197	func waitForTranscriptFlush(ctx context.Context, transcriptPath string, hookStartTime time.Time) {
198		const (
199			maxWait      = 3 * time.Second
200			pollInterval = 50 * time.Millisecond
201			tailBytes    = 4096
202			maxSkew      = 2 * time.Second
203		)
204	
205		logCtx := logging.WithComponent(ctx, "agent.claudecode")
206	
207		// Fast path: skip the poll loop when the sentinel can't possibly appear.
208		// - File doesn't exist: nothing to poll.
209		// - File is stale (unmodified for 2+ min): agent isn't running anymore.
210		//   This avoids 3s timeouts per stale "active" session (e.g., agent crashed
211		//   without firing stop hook).
212		const staleThreshold = 2 * time.Minute
213		info, err := os.Stat(transcriptPath)
214		if err != nil {
215			// Most likely the file doesn't exist; other errors (permission, etc.)
216			// would also prevent polling, so skip the wait either way.
217			return
218		}
219		fileAge := time.Since(info.ModTime())
220		if fileAge > staleThreshold {
221			logging.Debug(logCtx, "transcript file is stale, skipping sentinel wait",
222				slog.Duration("file_age", fileAge),
223			)
224			return
225		}
226	
227		deadline := time.Now().Add(maxWait)
228		for time.Now().Before(deadline) {
229			if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
230				logging.Debug(logCtx, "transcript flush sentinel found",
231					slog.Duration("wait", time.Since(hookStartTime)),
232				)
233				return
234			}
235			time.Sleep(pollInterval)
236		}
237		logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
238			slog.Duration("timeout", maxWait),
239		)
240	}
241	
242	// checkStopSentinel reads the tail of the transcript file and looks for the sentinel.
243	func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
244		f, err := os.Open(path) //nolint:gosec // path comes from agent hook input
245		if err != nil {
246			return false
247		}
248		defer f.Close()
249	
250		info, err := f.Stat()
251		if err != nil {
252			return false
253		}
254		offset := info.Size() - tailBytes
255		if offset < 0 {
256			offset = 0
257		}
258		buf := make([]byte, info.Size()-offset)
259		if _, err := f.ReadAt(buf, offset); err != nil {
260			return false
261		}
262	
263		lines := strings.Split(string(buf), "\n")
264		for _, line := range lines {
265			line = strings.TrimSpace(line)
266			if line == "" || !strings.Contains(line, stopHookSentinel) {
267				continue
268			}
269	
270			var entry struct {
271				Timestamp string `json:"timestamp"`
272			}
273			if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
274				continue
275			}
276			ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
277			if err != nil {
278				ts, err = time.Parse(time.RFC3339, entry.Timestamp)
279				if err != nil {
280					continue
281				}
282			}
283			// Validate timestamp is within acceptable range:
284			// - Not too far in the past (before hook started minus skew)
285			// - Not too far in the future (after hook started plus skew)
286			lowerBound := hookStartTime.Add(-maxSkew)
287			upperBound := hookStartTime.Add(maxSkew)
288			if ts.After(lowerBound) && ts.Before(upperBound) {
289				return true
290			}
291		}
292		return false
293	}
