29	// AsHookSupport returns the agent as HookSupport if it both implements the
30	// interface and (for CapabilityDeclarer agents) has declared the capability.
31	func AsHookSupport(ag Agent) (HookSupport, bool) {
32		if ag == nil {
33			return nil, false
34		}
35		hs, ok := ag.(HookSupport)
36		if !ok {
37			return nil, false
38		}
39		if cd, ok := ag.(CapabilityDeclarer); ok {
40			return hs, cd.DeclaredCapabilities().Hooks
41		}
42		return hs, true
43	}
